function describePayment(payment) {
  const methods = [];
  if (payment.cashAmount !== null) methods.push('現金');
  if (payment.cardNumber !== null) methods.push('信用卡');
  if (payment.checkNumber !== null) methods.push('支票');
  return methods.join('、');
}

const invalidPayment = { cashAmount: 100, cardNumber: '1234', checkNumber: null };
console.log(describePayment(invalidPayment));

