type Payment =
  | { tag: 'Cash'; amount: number }
  | { tag: 'Card'; cardNumber: string }
  | { tag: 'Check'; checkNumber: string };

const payment1: Payment = { tag: 'Cash', amount: 100 };
// const payment2: Payment = { tag: 'Cash', amount: 100, cardNumber: '1234' };
// ↑ TypeScript 編譯期就會直接報錯：Cash 這個 tag 沒有 cardNumber 這個欄位，
//   不是靠執行期檢查擋下來的

function describeOptional(opt) {
  if (opt.tag === 'Some') return `有值：${opt.value}`;
  return '沒有值';
}

const middleName1 = { tag: 'Some', value: '大' };
const middleName2 = { tag: 'None' };

console.log(describeOptional(middleName1));
console.log(describeOptional(middleName2));

